from collections import deque


def waves(graph, targets, changed, cached):
    # Compute scope (targets + transitive prerequisites) and detect missing names
    scope = set()
    missing = set()
    stack = list(targets)
    while stack:
        job = stack.pop()
        if job in scope:
            continue
        scope.add(job)
        if job not in graph:
            missing.add(job)
        else:
            for prereq in graph[job]:
                if prereq not in scope:
                    stack.append(prereq)

    if missing:
        raise ValueError(f"missing: {min(missing)}")

    # Build prerequisite sets and reverse edges (dependents)
    prereq_set = {j: set(graph[j]) for j in scope}
    dependents = {j: [] for j in scope}
    for j in scope:
        for p in prereq_set[j]:
            dependents[p].append(j)

    # Cycle detection using iterative DFS with three colors
    color = {j: 0 for j in scope}  # 0=unvisited, 1=visiting, 2=done
    for start in scope:
        if color[start] != 0:
            continue
        stack = [(start, 0)]
        color[start] = 1
        while stack:
            node, idx = stack[-1]
            neighbors = graph[node]
            if idx < len(neighbors):
                stack[-1] = (node, idx + 1)
                nb = neighbors[idx]
                c = color.get(nb, 0)
                if c == 0:
                    color[nb] = 1
                    stack.append((nb, 0))
                elif c == 1:
                    raise ValueError("cycle")
            else:
                color[node] = 2
                stack.pop()

    # Topological order via Kahn's algorithm
    in_degree = {j: len(prereq_set[j]) for j in scope}
    queue = deque([j for j in scope if in_degree[j] == 0])
    topo = []
    while queue:
        j = queue.popleft()
        topo.append(j)
        for dep in dependents[j]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                queue.append(dep)

    # Compute which jobs need building
    needs_build = set()
    for job in topo:  # prerequisites come before dependents
        if job in changed or job not in cached or any(p in needs_build for p in prereq_set[job]):
            needs_build.add(job)

    # Compute parallel waves
    wave = {}
    for job in topo:
        if job not in needs_build:
            continue
        max_w = -1
        for p in prereq_set[job]:
            if p in needs_build:
                if wave[p] > max_w:
                    max_w = wave[p]
        wave[job] = max_w + 1 if max_w >= 0 else 0

    if not wave:
        return []

    max_wave = max(wave.values())
    result = []
    for w in range(max_wave + 1):
        group = sorted([j for j in needs_build if wave[j] == w])
        result.append(group)

    return result

